-- Agency owns guard qualification. Platform does not independently verify ordinary guard credentials.
-- Every assignment requires agency membership + agency approval + no schedule conflict.
-- Armed work additionally requires the agency to attest a current armed qualification.

create or replace function public.assign_guard_rc2(p_job_id uuid,p_guard_id uuid)
returns jsonb language plpgsql security definer set search_path=public set row_security=off as $$
declare v_user_id uuid:=auth.uid();v_agency_id uuid;v_agency_status public.agency_status;v_job public.marketplace_jobs;v_guard public.guards;v_assignment public.job_assignments;v_armed boolean;
begin
 if v_user_id is null then raise exception 'SESSION_REQUIRED' using errcode='42501';end if;select agency_id,agency_status into v_agency_id,v_agency_status from public.resolve_my_agency_workspace();if v_agency_id is null or v_agency_status<>'approved' then raise exception 'AGENCY_NOT_APPROVED' using errcode='42501';end if;
 select * into v_job from public.marketplace_jobs where id=p_job_id for update;if v_job.id is null then raise exception 'MISSION_NOT_FOUND' using errcode='22023';end if;if v_job.accepted_agency_id is distinct from v_agency_id then raise exception 'MISSION_NOT_OWNED_BY_AGENCY' using errcode='42501';end if;if v_job.status<>'accepted' then raise exception 'MISSION_NOT_AWAITING_GUARD' using errcode='22023';end if;if v_job.payment_status not in('authorized','captured') then raise exception 'MISSION_PAYMENT_NOT_AUTHORIZED' using errcode='22023';end if;
 select * into v_assignment from public.job_assignments where job_id=p_job_id for update;if v_assignment.id is null or v_assignment.agency_id is distinct from v_agency_id then raise exception 'ASSIGNMENT_NOT_FOUND' using errcode='22023';end if;if v_assignment.status<>'awaiting_guard' or v_assignment.guard_id is not null then raise exception 'ASSIGNMENT_ALREADY_OFFERED_OR_LOCKED' using errcode='22023';end if;
 select * into v_guard from public.guards where id=p_guard_id and agency_id=v_agency_id and agency_approved=true for update;if v_guard.id is null then raise exception 'GUARD_NOT_APPROVED_BY_AGENCY' using errcode='42501';end if;v_armed:=v_job.service_type='armed_guard';if v_armed and not exists(select 1 from public.guard_credentials gc where gc.guard_id=p_guard_id and gc.credential_type='armed_qualification' and gc.verification_status='verified' and(gc.expires_on is null or gc.expires_on>=current_date)) then raise exception 'GUARD_ARMED_CREDENTIAL_NOT_VERIFIED' using errcode='22023';end if;if public.guard_has_schedule_conflict_rc1(p_guard_id,p_job_id) then raise exception 'GUARD_SCHEDULE_CONFLICT' using errcode='22023';end if;
 update public.job_assignments set guard_id=p_guard_id,status='offered',assigned_at=now(),offered_at=now(),accepted_at=null,declined_at=null,locked_at=null,response_deadline=now()+interval '15 minutes',assignment_version=assignment_version+1 where id=v_assignment.id and status='awaiting_guard' and guard_id is null;if not found then raise exception 'ASSIGNMENT_ALREADY_OFFERED_OR_LOCKED' using errcode='22023';end if;
 update public.marketplace_jobs set status='assigned',updated_at=now() where id=p_job_id and status='accepted' and payment_status in('authorized','captured');if not found then raise exception 'MISSION_NOT_ASSIGNABLE' using errcode='22023';end if;insert into public.mission_events(job_id,actor_user_id,event_type,payload) values(p_job_id,v_user_id,'guard_assignment_offered',jsonb_build_object('agency_id',v_agency_id,'guard_id',p_guard_id,'response_deadline',now()+interval '15 minutes','assignment_version',v_assignment.assignment_version+1,'agency_guard_gate','approved','armed_gate',case when v_armed then 'agency_attested' else 'not_required' end,'schedule_gate','clear'));return jsonb_build_object('success',true,'job_id',p_job_id,'guard_id',p_guard_id,'status','offered');
end $$;
revoke all on function public.assign_guard_rc2(uuid,uuid) from public,anon;grant execute on function public.assign_guard_rc2(uuid,uuid) to authenticated,service_role;

create or replace function public.assign_guard_slot_rc1(p_job_id uuid,p_slot_number integer,p_guard_id uuid)
returns jsonb language plpgsql security definer set search_path=public set row_security=off as $$
declare v_user uuid:=auth.uid();v_agency uuid;v_astatus public.agency_status;v_job public.marketplace_jobs;v_guard public.guards;v_slot public.job_guard_slots;v_filled integer;v_required integer;
begin
 if v_user is null then raise exception 'SESSION_REQUIRED' using errcode='42501';end if;select agency_id,agency_status into v_agency,v_astatus from public.resolve_my_agency_workspace();if v_agency is null or v_astatus<>'approved' then raise exception 'AGENCY_NOT_APPROVED' using errcode='42501';end if;
 select * into v_job from public.marketplace_jobs where id=p_job_id for update;if v_job.id is null or v_job.accepted_agency_id is distinct from v_agency then raise exception 'MISSION_NOT_OWNED_BY_AGENCY' using errcode='42501';end if;if v_job.payment_status not in('authorized','captured') or v_job.status not in('accepted','assigned') then raise exception 'MISSION_NOT_ASSIGNABLE' using errcode='22023';end if;
 v_required:=greatest(1,least(20,coalesce(v_job.required_guards,1)));if v_required<=1 then raise exception 'USE_SINGLE_GUARD_ASSIGNMENT' using errcode='22023';end if;if p_slot_number<1 or p_slot_number>v_required then raise exception 'INVALID_GUARD_SLOT' using errcode='22023';end if;perform public.ensure_job_guard_slots(p_job_id);select * into v_slot from public.job_guard_slots where job_id=p_job_id and slot_number=p_slot_number for update;if v_slot.guard_id is not null or v_slot.status<>'awaiting_guard' then raise exception 'GUARD_SLOT_ALREADY_FILLED' using errcode='22023';end if;
 select * into v_guard from public.guards where id=p_guard_id and agency_id=v_agency and agency_approved=true for update;if v_guard.id is null then raise exception 'GUARD_NOT_APPROVED_BY_AGENCY' using errcode='42501';end if;if v_job.service_type='armed_guard' and not exists(select 1 from public.guard_credentials gc where gc.guard_id=p_guard_id and gc.credential_type='armed_qualification' and gc.verification_status='verified' and(gc.expires_on is null or gc.expires_on>=current_date)) then raise exception 'GUARD_ARMED_CREDENTIAL_NOT_VERIFIED' using errcode='22023';end if;
 if exists(select 1 from public.job_guard_slots where job_id=p_job_id and guard_id=p_guard_id and status<>'cancelled') then raise exception 'GUARD_ALREADY_ASSIGNED_TO_JOB' using errcode='22023';end if;if public.guard_has_schedule_conflict_rc1(p_guard_id,p_job_id) then raise exception 'GUARD_SCHEDULE_CONFLICT' using errcode='22023';end if;
 delete from public.guard_slot_mission_state where slot_id=v_slot.id;update public.job_guard_slots set guard_id=p_guard_id,status='offered',offered_at=now(),accepted_at=null,declined_at=null,route_started_at=null,arrived_at=null,completed_at=null,updated_at=now() where id=v_slot.id and guard_id is null and status='awaiting_guard';if not found then raise exception 'GUARD_SLOT_ALREADY_FILLED' using errcode='22023';end if;
 update public.marketplace_jobs set status='assigned',updated_at=now() where id=p_job_id;select count(*) into v_filled from public.job_guard_slots where job_id=p_job_id and guard_id is not null and status<>'cancelled';insert into public.mission_events(job_id,actor_user_id,event_type,payload) values(p_job_id,v_user,'guard_staffing_slot_offered',jsonb_build_object('agency_id',v_agency,'guard_id',p_guard_id,'slot_number',p_slot_number,'filled_slots',v_filled,'required_guards',v_required));return jsonb_build_object('success',true,'job_id',p_job_id,'guard_id',p_guard_id,'slot_number',p_slot_number,'filled_slots',v_filled,'required_guards',v_required,'status','offered');
end $$;
revoke all on function public.assign_guard_slot_rc1(uuid,integer,uuid) from public,anon;grant execute on function public.assign_guard_slot_rc1(uuid,integer,uuid) to authenticated,service_role;
